func pop(stack *[]int) (int, error) {
	if len(*stack) == 0 {
		return 0, errEmptyStack
	}
	v := (*stack)[len(*stack)-1]
	*stack = (*stack)[:len(*stack)-1]
	return v, nil
}

func binop(stack *[]int, f func(a, b int) (int, error)) error {
	b, err := pop(stack)
	if err != nil {
		return err
	}
	a, err := pop(stack)
	if err != nil {
		return err
	}
	v, err := f(a, b)
	if err != nil {
		return err
	}
	*stack = append(*stack, v)
	return nil
}
```

Wait, about the error when there's only one value: the explainText says "only one value on the stack". If the first pop succeeds and the second fails, we return errEmptyStack, but the message should be "only one value on the stack". The tests don't check messages, but let's do it properly: check len first.

```go
func binop(stack *[]int, f func(a, b int) (int, error)) error {
	if len(*stack) < 2 {
		if len(*stack) == 0 {
			return errEmptyStack
		}
		return errOneValue
	}
	b := (*stack)[len(*stack)-1]
	a := (*stack)[len(*stack)-2]
	v, err := f(a, b)
	if err != nil {
		return err
	}
	*stack = append((*stack)[:len(*stack)-2], v)
	return nil
}
```

