```go
var builtins = map[string]func(*[]int) error{
	"+": func(s *[]int) error { return binop(s, func(a, b int) (int, error) { return a + b, nil }) },
	"-": ...,
	"*": ...,
	"/": func(s *[]int) error {
		if len(*s) < 2 { ... }
