```go
func Forth(input []string) ([]int, error) {
	words := map[string]*definition{}
	for name, fn := range builtins {
		words[name] = &definition{ops: []op{{builtin: fn}}}
	}

	stack := []int{}
	for _, line := range input {
		tokens := strings.Fields(line)
		for len(tokens) > 0 {
			tok := tokens[0]
			tokens = tokens[1:]
			if tok == ":" {
				// definition
				if len(tokens) == 0 {
					return nil, errIllegal
				}
				name := strings.ToLower(tokens[0])
				tokens = tokens[1:]
				if isNumber(name) {
					return nil, errIllegal
				}
				var ops []op
				for len(tokens) > 0 && tokens[0] != ";" {
					op, err := compileToken(tokens[0], words)
					if err != nil {
						return nil, err
					}
					ops = append(ops, op)
					tokens = tokens[1:]
				}
				if len(tokens) == 0 {
					return nil, errors.New("definition not terminated")
				}
				tokens = tokens[1:] // consume ";"
				words[name] = &definition{ops: ops}
				continue
			}
			op, err := compileToken(tok, words)
			if err != nil {
				return nil, err
			}
			if err := execOp(&stack, op); err != nil {
				return nil, err
			}
		}
	}
	return stack, nil
}
```

