package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var (
	errEmptyStack  = errors.New("empty stack")
	errOneValue    = errors.New("only one value on the stack")
	errDivideZero  = errors.New("divide by zero")
	errUndefined   = errors.New("undefined operation")
	errIllegal     = errors.New("illegal operation")
	errUnterminated = errors.New("definition not terminated")
)

// op is a single compiled instruction: a number to push, a built-in
// stack operation, or a reference to a user-defined word.
type op struct {
	num     int
	builtin func(*[]int) error
	def     *definition
}

// definition is the compiled body of a word.
type definition struct {
	ops []op
}

func (d *definition) exec(stack *[]int) error {
	for _, o := range d.ops {
		if err := execOp(stack, o); err != nil {
			return err
		}
	}
	return nil
}

func execOp(stack *[]int, o op) error {
	switch {
	case o.builtin != nil:
		return o.builtin(stack)
	case o.def != nil:
		return o.def.exec(stack)
	default:
		*stack = append(*stack, o.num)
		return nil
	}
}

func binop(stack *[]int, f func(a, b int) (int, error)) error {
	if len(*stack) < 2 {
		if len(*stack) == 0 {
			return errEmptyStack
		}
		return errOneValue
	}
	a := (*stack)[len(*stack)-2]
	b := (*stack)[len(*stack)-1]
	v, err := f(a, b)
	if err != nil {
		return err
	}
	*stack = append((*stack)[:len(*stack)-2], v)
	return nil
}

func unop(stack *[]int, f func(a int) (int, error)) error {
	if len(*stack) == 0 {
		return errEmptyStack
	}
	a := (*stack)[len(*stack)-1]
	v, err := f(a)
	if err != nil {
		return err
	}
	*stack = append(*stack, v)
	return nil
}

var builtins = map[string]func(*[]int) error{
	"+": func(s *[]int) error {
		return binop(s, func(a, b int) (int, error) { return a + b, nil })
	},
	"-": func(s *[]int) error {
		return binop(s, func(a, b int) (int, error) { return a - b, nil })
	},
	"*": func(s *[]int) error {
		return binop(s, func(a, b int) (int, error) { return a * b, nil })
	},
	"/": func(s *[]int) error {
		return binop(s, func(a, b int) (int, error) {
			if b == 0 {
				return 0, errDivideZero
			}
			return a / b, nil
		})
	},
	"dup": func(s *[]int) error {
		return unop(s, func(a int) (int, error) { return a, nil })
	},
	"drop": func(s *[]int) error {
		if len(*s) == 0 {
			return errEmptyStack
		}
		*s = (*s)[:len(*s)-1]
		return nil
	},
	"swap": func(s *[]int) error {
		if len(*s) < 2 {
			if len(*s) == 0 {
				return errEmptyStack
			}
			return errOneValue
		}
		(*s)[len(*s)-2], (*s)[len(*s)-1] = (*s)[len(*s)-1], (*s)[len(*s)-2]
		return nil
	},
	"over": func(s *[]int) error {
		if len(*s) < 2 {
			if len(*s) == 0 {
				return errEmptyStack
			}
			return errOneValue
		}
		return unop(s, func(a int) (int, error) { return a, nil })
	},
}

func isNumber(s string) bool {
	i := 0
	if s[0] == '-' {
		if len(s) == 1 {
			return false
		}
		i = 1
	}
	for _, c := range s[i:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

// compileToken resolves a token against the current word table. Word
// references are captured by pointer, so a definition keeps referring
// to the meaning of a word as it was when the definition was made.
func compileToken(tok string, words map[string]*definition) (op, error) {
	if isNumber(tok) {
		n, err := strconv.Atoi(tok)
		if err != nil {
			return op{}, errIllegal
		}
		return op{num: n}, nil
	}
	d, ok := words[strings.ToLower(tok)]
	if !ok {
		return op{}, fmt.Errorf("%s: %w", tok, errUndefined)
	}
	return op{def: d}, nil
}

func Forth(input []string) ([]int, error) {
	words := make(map[string]*definition, len(builtins))
	for name, fn := range builtins {
		words[name] = &definition{ops: []op{{builtin: fn}}}
	}

	stack := []int{}
	for _, line := range input {
		tokens := strings.Fields(line)
		for len(tokens) > 0 {
			tok := tokens[0]
			tokens = tokens[1:]
			if tok == ":" {
				if len(tokens) == 0 {
					return nil, errIllegal
				}
				name := strings.ToLower(tokens[0])
				tokens = tokens[1:]
				if isNumber(name) {
					return nil, errIllegal
				}
				var ops []op
				for len(tokens) > 0 && tokens[0] != ";" {
					o, err := compileToken(tokens[0], words)
					if err != nil {
						return nil, err
					}
					ops = append(ops, o)
					tokens = tokens[1:]
				}
				if len(tokens) == 0 {
					return nil, errUnterminated
				}
				tokens = tokens[1:] // consume ";"
				words[name] = &definition{ops: ops}
				continue
			}
			o, err := compileToken(tok, words)
			if err != nil {
				return nil, err
			}
			if err := execOp(&stack, o); err != nil {
				return nil, err
			}
		}
	}
	return stack, nil
}

